<script setup>
import PublishDelivery from "./PublishDelivery.vue";
import ReworkDevelopment from "./ReworkDevelopment.vue";
import { useRouter } from "vue-router";
import AppSelect from "../../shared/components/AppSelect.vue";
import { formatDate, translate } from "../../shared/i18n/index.js";
import { usePageTitle } from "../../shared/components/page-title.js";
import { computed, ref, watch } from "vue";
import { appApi } from "../../shared/api/api.js";
import { useResource } from "../../shared/api/use-resource.js";
import PageHeader from "../../shared/components/PageHeader.vue";
import StatusBadge from "../../shared/components/StatusBadge.vue";
import FeedbackMessage from "../../shared/components/FeedbackMessage.vue";
import MarkdownContent from "../../shared/components/MarkdownContent.vue";
const props = defineProps({ projectId: { type: String, required: true }, deliveryId: { type: String, required: true } });
const emit = defineEmits(["back"]);
const endpoint = `/projects/${props.projectId}/deliveries/${props.deliveryId}`;
const { data, loading, saving, error, reload, save } = useResource(() => appApi(endpoint));
usePageTitle(() => [error.value ? "" : data.value?.delivery.title, translate("交付")]);
const router = useRouter(), resubmitting = ref(false);
const reviewers = useResource(() => appApi(`/projects/${props.projectId}/reviewers`));
const reviewerId = ref("");
const checked = ref([]), note = ref("");
const canReview = computed(() => data.value?.canReview && data.value?.permissions.includes("deliverable.review") && data.value.delivery.status === "pending" && data.value.issue?.release?.status !== "archived");
const outcome = trigger => data.value?.issue?.workflowActions?.find(edge => edge.trigger === trigger);
const allowed = trigger => !data.value?.issue || Boolean(outcome(trigger)?.allowed);
const label = (trigger, fallback) => outcome(trigger)?.name || (data.value?.issue ? '' : fallback);
watch(canReview, allowed => { if (!allowed) { checked.value = []; note.value = ""; } });
function resubmitted(value) { resubmitting.value = false; void router.push({ name: "deliveries", query: { projectId: props.projectId, delivery: value.id } }); }
function reassign() { return save(`${endpoint}/assign`, { revision: data.value.delivery.revision, reviewerId: reviewerId.value }, () => { reviewerId.value = ""; void reload(); }); }
function begin() { return save(`${endpoint}/start`, { revision: data.value.delivery.revision }, () => { void reload(); }); }
function review(status) { if (!canReview.value) return; return save(`${endpoint}/review`, { revision: data.value.delivery.revision, status, checkedItems: checked.value, reviewNote: note.value }, () => { void reload(); }, status === "accepted" ? "交付已通过验收。" : "已退回交付，并记录原因。"); }
</script>
<template><button class="ui-back" @click="emit('back')">{{ $t("← 返回交付") }}</button><FeedbackMessage :message="error" type="error" /><button v-if="error" @click="reload">{{ $t("重新读取") }}</button><p v-if="loading && !data" role="status">{{ $t("正在读取交付…") }}</p><template v-if="data"><PageHeader :title="data.delivery.title" :description="$t('审阅成果，逐项核对，再记录验收结论。')"><StatusBadge :tone="data.delivery.status === 'accepted' ? 'success' : 'neutral'">{{ { pending: $t("待验证"), accepted: $t("已通过"), returned: $t("已退回") }[data.delivery.status] }}</StatusBadge></PageHeader><div class="ui-detail-columns"><div><section class="ui-content-section"><h2>{{ $t("交付说明") }}</h2><MarkdownContent :content="data.delivery.body" /></section><section class="ui-content-section"><p v-if="data.delivery.status === 'pending'">{{ $t("验证进度") }}：{{ $t(data.delivery.verificationStartedAt ? "验证中" : "待开始验证") }}</p><button v-if="canReview && !data.delivery.verificationStartedAt && allowed('verification.started')" :disabled="saving" @click="begin">{{ label('verification.started', $t('开始验证')) }}</button><h2>{{ $t("验收核对") }}</h2><label v-for="(item, index) in data.delivery.checklist" :key="index" class="ui-check-row"><input v-if="canReview" v-model="checked" type="checkbox" :value="index" :disabled="saving" /><input v-else type="checkbox" :checked="data.delivery.checkedItems.includes(index)" disabled /><span>{{ item }}</span></label></section><form v-if="canReview" class="project-form ui-content-section" @submit.prevent="review('accepted')"><label>{{ $t("验收说明") }}<textarea v-model="note" rows="4" maxlength="4000" :disabled="saving" :placeholder="$t('记录验证结果；退回时请说明原因。')" /></label><p v-if="data.issue" class="field-hint">{{ $t('通过后进入') }}：{{ outcome('verification.accepted')?.statusName || $t('当前流程不允许') }}；{{ $t('退回后进入') }}：{{ outcome('verification.returned')?.statusName || $t('当前流程不允许') }}</p><div class="actions"><button v-if="allowed('verification.accepted')" type="submit" class="primary" :disabled="saving || checked.length !== data.delivery.checklist.length || !allowed('verification.accepted')">{{ label('verification.accepted', $t('通过验收')) }}</button><button v-if="allowed('verification.returned')" type="button" :disabled="saving || !note.trim() || !allowed('verification.returned')" @click="review('returned')">{{ label('verification.returned', $t('退回修改')) }}</button></div></form><section v-else-if="data.delivery.reviewedAt" class="ui-content-section"><h2>{{ $t("验收记录") }}</h2><p>{{ data.people.find(p => p.id === data.delivery.reviewedById)?.displayName }} · {{ formatDate(data.delivery.reviewedAt, { hour: "2-digit", minute: "2-digit" }) }}</p><p class="project-text">{{ data.delivery.reviewNote || $t("全部核对项已确认。") }}</p></section></div><aside class="ui-detail-aside"><template v-if="data.issue"><h2>{{ $t("关联事项") }}</h2><RouterLink :to="{ name: 'project', params: { projectId }, query: { tab: data.issue.type === 'bug' ? 'bugs' : 'issues', issue: data.issue.id } }">#{{ data.issue.number }} {{ data.issue.title }}</RouterLink><p class="muted">{{ data.issue.statusName }}</p></template><p v-else>{{ $t("独立开发交付") }}</p><h3>{{ $t("提交标识") }}</h3><code>{{ data.delivery.commit || $t("未提供") }}</code><h3>{{ $t("交付验证人") }}</h3><p>{{ data.people.find(p => p.id === data.delivery.reviewerId)?.displayName || $t("历史成员") }}</p><div v-if="data.delivery.supersededById || data.delivery.supersedesId || data.developmentTask || data.canResubmit" class="delivery-followup-actions"><RouterLink v-if="data.delivery.supersededById" :to="{ name: 'deliveries', query: { projectId, delivery: data.delivery.supersededById } }">{{ $t("查看重新提交的交付") }}</RouterLink><RouterLink v-if="data.delivery.supersedesId" :to="{ name: 'deliveries', query: { projectId, delivery: data.delivery.supersedesId } }">{{ $t("查看原交付") }}</RouterLink><template v-if="data.developmentTask"><ReworkDevelopment :key="data.developmentTask.id + ':' + data.developmentTask.revision" :project-id="projectId" :task="data.developmentTask" /><RouterLink :to="{ name: 'project', params: { projectId }, query: { tab: 'tasks', task: data.developmentTask.replacedByTaskId || data.developmentTask.id } }">{{ $t('查看开发任务') }}</RouterLink></template><button v-if="data.canResubmit && (!data.issue || data.issue.deliverySubmission?.allowed) && data.permissions.includes('deliverable.create') && data.issue?.release?.status !== 'archived'" @click="resubmitting = true">{{ data.issue?.deliverySubmission?.label || $t('修改并重新提交') }}</button></div><form v-if="data.delivery.status === 'pending' && data.permissions.includes('issue.assign') && data.issue?.release?.status !== 'archived'" class="project-form" @submit.prevent="reassign"><FeedbackMessage :message="reviewers.error.value" type="error" /><label>{{ $t("重新指定验证人") }}<AppSelect search-pinyin native-events v-model="reviewerId" :aria-label="$t('重新指定验证人')" :disabled="saving || reviewers.loading.value"><option value="">{{ $t("选择明确的验证人") }}</option><option v-for="person in reviewers.data.value?.items || []" :key="person.id" :value="person.id">{{ person.displayName }}（{{ person.username }}）</option></AppSelect></label><button :disabled="saving || !reviewerId">{{ $t("确认分派") }}</button></form><h3>{{ $t("发布人") }}</h3><p>{{ data.people.find(p => p.id === data.delivery.authorId)?.displayName || $t("历史成员") }}</p></aside></div><PublishDelivery v-if="resubmitting" :project-id="projectId" :previous="data.delivery" @close="resubmitting = false" @published="resubmitted" /></template></template>

<style scoped>
.delivery-followup-actions { display: flex; flex-direction: column; align-items: flex-start; gap: 12px; margin-top: 24px; }
</style>
